// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address ownerEOA, address newOwner, bool viaForwarder) public {
        vm.assume(ownerEOA != address(0));
        vm.assume(newOwner != address(0));
        vm.deal(ownerEOA, 1 ether);

        vm.prank(ownerEOA);
        c.initialize();

        bool ok;

        if (!viaForwarder) {
            vm.prank(ownerEOA);
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
            assertTrue(c.owner() == newOwner);
        } else {
            Forwarder f = new Forwarder();

            vm.deal(address(f), 0.1 ether);

            vm.prank(ownerEOA);
            try f.callTransferOwnership(address(c), newOwner) {
                ok = true;
            } catch {
                ok = false;
            }

            assertTrue(ok == false && c.owner() == ownerEOA);
        }
    }
}

contract Forwarder {
    function callTransferOwnership(address target, address newOwner) external {
        (bool s, ) = target.call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        require(s, "forwarded call failed");
    }
}
